104	type replayRequest struct {
105		BatchID string `json:"batchId"`
106		Samples []struct {
107			EventID    string             `json:"eventId"`
108			ObservedAt string             `json:"observedAt"`
109			Values     map[string]float64 `json:"values"`
110		} `json:"samples"`
111	}
112	
113	func (h *handler) replay(w http.ResponseWriter, r *http.Request) {
114		var request replayRequest
115		if err := decodeSingleJSON(r, &request); err != nil {
116			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
117			return
118		}
119		if strings.TrimSpace(request.BatchID) == "" {
120			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "batchId is required"})
121			return
122		}
123		if len(request.Samples) < 1 || len(request.Samples) > 100 {
124			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "samples must contain between 1 and 100 entries"})
125			return
126		}
127		samples := make([]Sample, len(request.Samples))
128		seenEventIDs := make(map[string]struct{}, len(request.Samples))
129		for i, entry := range request.Samples {
130			eventID := strings.TrimSpace(entry.EventID)
131			if eventID == "" {
132				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "each sample requires a non-blank eventId"})
133				return
134			}
135			if _, dup := seenEventIDs[eventID]; dup {
136				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "eventId values must be unique within a batch"})
137				return
138			}
139			seenEventIDs[eventID] = struct{}{}
140			observedAt, err := time.Parse(time.RFC3339, entry.ObservedAt)
141			if err != nil {
142				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "observedAt must be RFC3339 formatted"})
143				return
144			}
145			if len(entry.Values) == 0 || hasBlankKey(entry.Values) {
146				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be a non-empty map with non-blank metric names"})
147				return
148			}
149			if !finiteValues(entry.Values) {
150				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be finite numbers"})
151				return
152			}
153			samples[i] = Sample{
154				EventID:    eventID,
155				ObservedAt: observedAt.UTC(),
156				Values:     cloneTelemetry(entry.Values),
157			}
158		}
159	
160		receipt, repeat, err := h.store.Replay(r.PathValue("id"), strings.TrimSpace(request.BatchID), samples)
161		if errors.Is(err, ErrDeviceNotFound) {
162			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
163			return
164		}
165		if errors.Is(err, ErrBatchConflict) {
166			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
167			return
168		}
169		if errors.Is(err, ErrStorageUnavailable) {
170			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
171			return
172		}
173		if err != nil {
174			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
175			return
176		}
177		status := http.StatusAccepted
178		if repeat {
179			status = http.StatusOK
180		}
181		writeJSON(w, status, receipt)
182	}
