296	func (h *handler) setRetention(w http.ResponseWriter, r *http.Request) {
297		var request struct {
298			MaxEvents *int64 `json:"maxEvents"`
299		}
300		if err := decodeSingleJSON(r, &request); err != nil || request.MaxEvents == nil {
301			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "maxEvents is required as a single integer"})
302			return
303		}
304		maxEvents := *request.MaxEvents
305		if maxEvents < 0 || maxEvents > maxRetentionEvents {
306			writeJSON(w, http.StatusBadRequest, map[string]string{
307				"error": fmt.Sprintf("maxEvents must be between 0 and %d", maxRetentionEvents),
308			})
309			return
310		}
311		status, err := h.store.SetRetention(r.PathValue("id"), maxEvents)
312		if errors.Is(err, ErrDeviceNotFound) {
313			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
314			return
315		}
316		if errors.Is(err, ErrStorageUnavailable) {
317			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
318			return
319		}
320		if err != nil {
321			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
322			return
323		}
324		writeJSON(w, http.StatusOK, status)
325	}
