329	func (h *handler) createRule(w http.ResponseWriter, r *http.Request) {
330		var request struct {
331			ID      string  `json:"id"`
332			Metric  string  `json:"metric"`
333			Trigger float64 `json:"trigger"`
334			Recover float64 `json:"recover"`
335		}
336		if err := decodeJSON(r, &request); err != nil {
337			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
338			return
339		}
340		ruleID := strings.TrimSpace(request.ID)
341		metric := strings.TrimSpace(request.Metric)
342		if ruleID == "" {
343			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
344			return
345		}
346		if metric == "" {
347			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric is required"})
348			return
349		}
350		if !finiteFloat(request.Trigger) || !finiteFloat(request.Recover) {
351			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "thresholds must be finite numbers"})
352			return
353		}
354		if request.Recover >= request.Trigger {
355			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
356			return
357		}
358		rule, err := h.store.CreateRule(r.PathValue("id"), ruleID, metric, request.Trigger, request.Recover)
359		if errors.Is(err, ErrDeviceNotFound) {
360			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
361			return
362		}
363		if errors.Is(err, ErrRuleConflict) {
364			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
365			return
366		}
367		if errors.Is(err, ErrStorageUnavailable) {
368			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
369			return
370		}
371		if err != nil {
372			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
373			return
374		}
375		writeJSON(w, http.StatusCreated, rule)
376	}
