515	func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
516		alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
517		if err != nil || alertID < 1 {
518			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
519			return
520		}
521		alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
522		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
523			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
524			return
525		}
526		if errors.Is(err, ErrStorageUnavailable) {
527			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
528			return
529		}
530		if err != nil {
531			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
532			return
533		}
534		writeJSON(w, http.StatusOK, alert)
535	}
536	
537	func finiteFloat(value float64) bool {
538		return !math.IsNaN(value) && !math.IsInf(value, 0)
539	}
540	
541	func hasBlankKey(values map[string]float64) bool {
542		for key := range values {
543			if strings.TrimSpace(key) == "" {
544				return true
545			}
546		}
547		return false
548	}
549	
550	func finiteValues(values map[string]float64) bool {
551		for _, value := range values {
552			if math.IsNaN(value) || math.IsInf(value, 0) {
553				return false
554			}
555		}
556		return true
557	}
558	
559	func decodeJSON(r *http.Request, target any) error {
560		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
561		decoder.DisallowUnknownFields()
562		return decoder.Decode(target)
563	}
564	
565	// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
566	// trailing data such as a second JSON object or concatenated documents.
567	func decodeSingleJSON(r *http.Request, target any) error {
568		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
569		decoder.DisallowUnknownFields()
570		if err := decoder.Decode(target); err != nil {
571			return err
572		}
573		var trailing any
574		if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
575			return errors.New("body must contain a single JSON value")
576		}
577		return nil
578	}
579	
580	func writeJSON(w http.ResponseWriter, status int, value any) {
581		w.Header().Set("Content-Type", "application/json")
582		w.WriteHeader(status)
583		_ = json.NewEncoder(w).Encode(value)
584	}
