1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound  = errors.New("device not found")
12		ErrBatchConflict   = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrRuleConflict    = errors.New("rule already exists")
16		ErrVersionConflict = errors.New("rule version conflict")
17		ErrInvalidRule     = errors.New("invalid rule")
18		// ErrHistoryGone means a continuation cursor's start record was trimmed by
19		// the retention limit before the next page was read.
20		ErrHistoryGone = errors.New("cursor start no longer retained")
21	)
22	
23	// maxRetentionEvents bounds a per-device history retention setting.
24	const maxRetentionEvents = 10000
25	
26	// RetentionStatus reports a device's history retention settings and counters.
27	// MaxEvents 0 means unlimited. EarliestSequence is nil for an empty history;
28	// MaxSequence is the highest sequence ever received (0 before any sample) and
29	// never retreats, even after trimming.
30	type RetentionStatus struct {
31		MaxEvents        int64  `json:"maxEvents"`
32		RetainedEvents   int64  `json:"retainedEvents"`
33		EarliestSequence *int64 `json:"earliestSequence"`
34		MaxSequence      int64  `json:"maxSequence"`
35	}
