132	// StoredBatch records the ordered samples an accepted batchId committed along
133	// with the receipt returned on first acceptance, so a repeated batchId can be
134	// checked for identical content and replayed with the original receipt.
135	type storedBatch struct {
136		samples []Sample
137		receipt ReplayReceipt
138	}
