100	func decodeBody[T any](t *testing.T, result *httptest.ResponseRecorder) T {
101		t.Helper()
102		var value T
103		if err := json.Unmarshal(result.Body.Bytes(), &value); err != nil {
104			t.Fatalf("decode %s: %v", result.Body.String(), err)
105		}
