118	func walkHistory(t *testing.T, h http.Handler, target string) []historyResponse {
119		t.Helper()
120		var pages []historyResponse
121		cursor := ""
122		for {
123			url := target
124			if cursor != "" {
125				url += "&cursor=" + cursor
126			}
127			result := doRequest(t, h, http.MethodGet, url, "")
128			if result.Code != http.StatusOK {
129				t.Fatalf("history status = %d body = %s", result.Code, result.Body.String())
130			}
131			page := decodeBody[historyResponse](t, result)
132			pages = append(pages, page)
133			if page.NextCursor == nil {
134				return pages
135			}
136			cursor = *page.NextCursor
137		}
138	}
