func TestReplayScopesIdentifiersPerDevice(t *testing.T) {
	h := NewHandler(NewStore())
	mustRegister(t, h, "a")
	mustRegister(t, h, "b")

	body := replayBody("shared-batch", sample("shared-event", "2024-01-02T10:00:00Z", `{"v":1}`))
