		"non-finite values": `{"batchId":"b","samples":[` + sample("e1", "2024-01-02T10:00:00Z", `{"v":1e999}`) + `]}`,
		"duplicate eventId": `{"batchId":"b","samples":[` + good + `,` + good + `]}`,
