// finiteMetricValues converts the raw JSON metric map into float64 values.
// Every entry must decode to a finite JSON number: null would otherwise become
// the zero value silently, and strings, booleans, objects and arrays are not
// metric values either. A nil entry (JSON null) is explicitly rejected rather
// than treated as an unprovided pointer.
func finiteMetricValues(raw map[string]json.RawMessage) (map[string]float64, bool) {
	values := make(map[string]float64, len(raw))
	for key, token := range raw {
		var number float64
		if err := json.Unmarshal(token, &number); err != nil || !finiteFloat(number) {
			return nil, false
		}
		values[key] = number
	}
	return values, true
}

